    {
      "id": "u14",
      "kind": "EXAMPLE",
      "label": "Worked calculation of moles of oxygen gas from volume at STP",
      "excerpts": [
        {
          "text": "STP पर 44.8 L ऑक्सीजन गैस में मोल कितने होंगे?\n\n\\[\nn = \\frac{44.8}{22.4} = 2\\ \\text{mol}\n\\]",
          "occurrence": 0
        }
      ],
      "attributes": {
        "context": "abstract_or_hypothetical",
